	GRPCStreaming     = 128               // Dedicated flag for gRPC streaming
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
// For composite values, returns pipe-separated names of all set flags in ascending order.
func (tp Protocol) String() string {
	// Handle special cases first
